class Solution(object):
    def findCriticalAndPseudoCriticalEdges(self, n, edges):
        """
        :type n: int
        :type edges: List[List[int]]
        :rtype: List[List[int]]
        """
        def union(x, y):
            parents[find(y)] = find(x)

        def find(x):
            if parents[x] != x:
                parents[x] = find(parents[x])
            return parents[x]

        critical_edges = []
        pseudo_critical_edges = []
        sorted_edges = [[index] + i for index, i in enumerate(edges)]
        sorted_edges = sorted(sorted_edges, key=lambda x: x[-1])

        parents = list(range(n))
        mst_weight = 0
        for ind, a, b, w in sorted_edges:
            pa, pb = find(a), find(b)
            if pa != pb:
                union(pa, pb)
                mst_weight += w

        for i, edge in enumerate(sorted_edges):
            cur_edges = sorted_edges[:i] + sorted_edges[i + 1:]

            total1 = edge[3]
            parents = list(range(n))
            union(edge[1], edge[2])
            for ind, a, b, w in cur_edges:
                pa, pb = find(a), find(b)
                if pa != pb:
                    union(pa, pb)
                    total1 += w

            total2 = 0
            parents = list(range(n))
            for ind, a, b, w in cur_edges:
                pa, pb = find(a), find(b)
                if pa != pb:
                    union(pa, pb)
                    total2 += w

            if total1 == mst_weight:
                if total1 != total2:
                    critical_edges.append(edge[0])
                else:
                    pseudo_critical_edges.append(edge[0])
        return [critical_edges, pseudo_critical_edges]
